"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1010-08-15:0":{"b": ["Valencia (Balansiya) ilipita mikononi mwa wafuasi walioachwa huru wa Amirid Mubarak na Muzaffar", "38ac8e22"], "d": ["Kwa kuvunjika kwa utawala wa wajukuu wa Hajib Mansur, Balansiya iliingia chini ya utawala wa Mubarak na Muzaffar, walioachwa huru wa Waamirid; emirate za taifa zilianza kuonekana Andalusia.", "82f013cc"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1013-01-01:0":{"b": ["Sulayman al-Musta'in na wafuasi wake waliingia Córdoba na kumwondoa tena II. Hisham kwenye kiti cha enzi; wanazuoni wasiopungua sitini waliuawa mjini (403/1013; chanzo kinatoa mwaka, hakuna siku).", "e863c0b4"], "d": ["Sulayman al-Musta'in na wafuasi wake waliingia Córdoba na kumwondoa tena II. Hisham kwenye kiti cha enzi; wanazuoni wasiopungua sitini waliuawa mjini (403/1013; chanzo kinatoa mwaka, hakuna siku).", "e863c0b4"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1016-01-01:0":{"b": ["Wahammudid waliteka Córdoba na kiti cha enzi cha Andalusia", "a8a8ea65"], "d": ["Wahammudid wa Kishia, wanaodai kuwa wa ukoo wa Alawi, kwa kutumia udhaifu wa nasaba ya Umayyad, mwaka 1016 walichukua Córdoba na kiti cha enzi cha ukhalifa; Córdoba ilibaki chini ya utawala wao kati ya 1016-1022.", "b088ab2a"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1021-01-01:0":{"b": ["Nasaba ya Amirid ilianzishwa ikiwa na kitovu Balansiya (1021-1094)", "ebf0b6e2"], "d": ["Abd al-Aziz b. Abd al-Rahman, mjukuu wa Hajib al-Mansur, mwaka 1021 alianzisha emirate ya taifa ya Amirid yenye kitovu Balansiya; nasaba iliendelea na vipindi vya mapumziko hadi 1094.", "dc1ccee5"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1023-03-26:0":{"b": ["Kadhi Ibn Abbad alitangaza Ishbiliya kuwa kitovu cha serikali (Abbadid)", "931db55e"], "d": ["Kadhi Abu'l-Qasim Ibn Abbad alitangaza Ishbiliya kuwa kitovu cha serikali katika mwaka 414 (1023); emirate ya taifa ya Abbadid iligeuka kuwa mojawapo ya vitovu muhimu zaidi vya Andalusia.", "51e3b6d5"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1031-01-01:0":{"b": ["Córdoba ikawa jamhuri chini ya utawala wa Jawharid (1031-1070)", "943bc77c"], "d": ["Baada ya nasaba ya Umayyad kumalizika, Córdoba kutoka 1031 hadi 1070 ikawa jamhuri chini ya utawala wa Jawharid.", "6afd1a28"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1049-06-05:0":{"b": ["Waziri wa Fatimid al-Yazuri alipomteua mkuu wa Zughba kuwa emiri wa Tripolitania na Gabes, Banu Hilal waliinuka kuelekea magharibi (441, 1049).", "481a1144"], "d": ["Waziri wa Fatimid al-Yazuri alipomteua mkuu wa Zughba kuwa emiri wa Tripolitania na Gabes, Banu Hilal waliinuka kuelekea magharibi (441, 1049).", "481a1144"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1052-04-14:0":{"b": ["Huko Haydaran Mu'izz b. Badis alishindwa na Waarabu wa Hilali; eneo la Tripoli lilitoka kwenye udhibiti wa Zirid (11 Dhu al-Hijja 443).", "43d177c0"], "d": ["Huko Haydaran Mu'izz b. Badis alishindwa na Waarabu wa Hilali; eneo la Tripoli lilitoka kwenye udhibiti wa Zirid (11 Dhu al-Hijja 443).", "43d177c0"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1058-02-28:0":{"b": ["Waabbadid waliteka Algeciras (al-Jazira al-Khadra) kutoka kwa Wahammudid (450/1058)", "a2ac7bdd"], "d": ["Muhammad al-Mahdi, mwana wa Qasim, na mjukuu wake Qasim al-Wathiq walitawala Algeciras hadi ilipotekwa na Waabbadid (Taifa ya Seville) (450/1058); utawala wa nasaba ya Hammudid huko Algeciras ulimalizika hivyo.", "5c22a7ca"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1061-01-26:0":{"b": ["Utawala wa eneo la Fez uliachiwa Yusuf b. Tashfin (453, 1061).", "6c0af3bc"], "d": ["Utawala wa eneo la Fez uliachiwa Yusuf b. Tashfin (453, 1061).", "6c0af3bc"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1062-01-15:0":{"b": ["Abu Bakr b. Umar alianza ujenzi wa mji wa Marrakesh (454, 1062).", "1312fb2d"], "d": ["Abu Bakr b. Umar alianza ujenzi wa mji wa Marrakesh (454, 1062).", "1312fb2d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1065-11-10:0":{"b": ["Dhunnunid Yahya al-Ma'mun alimwondoa Amirid Abd al-Malik kwenye kiti cha enzi; Valencia (Balansiya) ilipita kwa Wadhunnunid", "3bb5a927"], "d": ["Mtawala wa Toledo (Tulaytula) Dhunnunid Yahya al-Ma'mun alimwondoa mtawala wa Amirid Abd al-Malik kwenye kiti chake cha enzi (8 Dhu al-Hijja 457 / 10 Novemba 1065); Wadhunnunid kati ya 457-462 (1065-1070) walitawala Shatiba na Balansiya (Valencia) zilizokuwa mikononi mwa Waamirid.", "aad35ff8"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1070-01-01:0":{"b": ["Córdoba ilipita kwa Waabbadid baada ya Wajawharid", "fc156474"], "d": ["Utawala wa Jawharid uliendelea hadi 1070; kisha Córdoba ilipita mikononi mwa emirate ya Abbadid yenye kitovu Ishbiliya.", "d8bc19d6"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1080-01-01:0":{"b": ["Waalmoravid waliteka Tlemcen, Oujda na Oran na kufika mji wa Algiers", "cefef422"], "d": ["Yusuf b. Tashfin, akielekea Maghrib ya Kati, aliteka Oujda, Tlemcen na Oran, na kufika mji wa Algiers (1080); alijenga huko Algiers al-Jami' al-Kabir.", "8bfdcd25"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1085-05-08:0":{"b": ["Toledo ilikabidhiwa kwa Castile; Dhunnunid Yahya al-Qadir alirudi Balansiya", "e0a87ca9"], "d": ["Mwishoni mwa kuzingirwa kulikodumu takriban miezi tisa, Toledo (Tulaytula) ilikabidhiwa kwa amani kwa Ufalme wa Castile wa VI. Alfonso (8 Mei 1085); mtawala wa Dhunnunid Yahya al-Qadir alienda Balansiya (Valencia) na familia yake na wasaidizi wake na kutawala huko. Katika atlasi Valencia kutoka siku hii inatoka kwenye kitambulisho cha Wadhunnunid (Taifa ya Toledo) na kupita kwenye rekodi ya Muluk at-Tawa'if (emirate za taifa za Andalusia).", "a494fcd4"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1086-06-30:0":{"b": ["Yusuf b. Tashfin alitua Algeciras (al-Jazira al-Khadra); kuvuka kwa kwanza kwenda Andalusia", "ad79ab8b"], "d": ["Kwa mwaliko wa emiri kumi na watatu wa Andalusia, Yusuf, kwa sharti la Algeciras kupewa yeye, alitua pwani tarehe 15 Rabi' al-Awwal 479 (30 Juni 1086) na kuvuka hadi Ishbiliya.", "77396cfd"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1086-10-23:0":{"b": ["Yusuf b. Tashfin aliliangamiza jeshi la Castile huko Zallaqa (12 Rajab 479).", "7f7d340d"], "d": ["Yusuf b. Tashfin aliliangamiza jeshi la Castile huko Zallaqa (12 Rajab 479).", "7f7d340d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1087-04-08:0":{"b": ["Abu Bakr b. Umar alikufa (480, 1087).", "00e73559"], "d": ["Abu Bakr b. Umar alikufa (480, 1087).", "00e73559"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1094-06-15:0":{"b": ["El Cid alichukua Valencia: Utawala wa Valencia (El Cid) ulianzishwa", "f5b81beb"], "d": ["Rodrigo Díaz de Vivar (El Cid), baada ya kuzingirwa, alichukua udhibiti wa Valencia (Balansiya) tarehe 15 Juni 1094; alimwacha Ibn Jahhaf kwenye wadhifa wa ukadhi. Valencia ilitoka kwenye rekodi ya Muluk at-Tawa'if (emirate za taifa za Andalusia) na kupita kwenye Utawala wa Valencia (El Cid).", "e51445ac"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-01-01:0":{"b": ["Waalmoravid waliteka Balansiya", "ce05cefc"], "d": ["Baada ya kifo cha Rodrigo mwaka 1099, Balansiya, iliyokuwa mikononi mwa mkewe Ximena, ilitekwa na Waalmoravid mwaka 1102.", "8407a408"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-05-05:0":{"b": ["Balansiya (Valencia) ilitekwa na Waalmoravid (1102)", "833a9c9a"], "d": ["Baada ya kifo cha El Cid mwaka 1099, mji ulibaki kwa mjane wake Jimena; Balansiya ilitekwa na Waalmoravid mwaka 1102. Valencia tarehe hii inatoka kwenye Utawala wa Valencia (El Cid) na kupita kwenye Dola ya Almoravid.", "a9ecdc4d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1106-09-04:0":{"b": ["Yusuf b. Tashfin alikufa Marrakesh; mwanawe Ali b. Yusuf alichukua nafasi yake", "3a60ecd3"], "d": ["Yusuf b. Tashfin alikufa Marrakesh; mwanawe Ali b. Yusuf alichukua nafasi yake", "3a60ecd3"]},
