"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1110-01-24:0":{"b": ["Emiri wa Hudid Ahmad al-Musta'in alikufa; jeshi la Almoravid lilitembea kuelekea Saraqusta", "8378eeaf"], "d": ["Kwa kifo cha Ahmad al-Musta'in-Billah (1 Rajab 503 / 24 Januari 1110), jeshi la Almoravid lilianza kusonga kutoka Balansiya kuelekea Saraqusta (Zaragoza).", "1303f83d"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1112-06-28:0":{"b": ["Ali b. Yusuf aliuzingira Tulaytula (Toledo) lakini hakuweza kuuteka", "d35d4a4e"], "d": ["Katika kuvuka kwa pili kwa Ali b. Yusuf kwenda Andalusia, Tulaytula ilizingirwa; kwa upinzani mkali kuzingirwa kuliondolewa (506/1112-13), lakini kwa upande mwingine Madrid na vitovu kadhaa vinavyoizunguka vilitekwa.", "106302f2"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1118-12-19:0":{"b": ["Mfalme wa Aragon I. Alfonso aliingia Zaragoza; mji ulipita kutoka kwa Waalmoravid kwa Aragon", "49a4a80d"], "d": ["Zaragoza, ambayo chakula chake kilimalizika mwishoni mwa kuzingirwa kwa muda mrefu, ilikubali masharti ya kujisalimisha tarehe 11 Desemba 1118; I. Alfonso aliingia mjini tarehe 18 Desemba. Zaragoza ikawa mji mkuu wa Ufalme wa Aragon.", "25de2b0c"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1121-11-13:0":{"b": ["Ibn Tumart alitangaza umahdi wake", "33dad2aa"], "d": ["Ibn Tumart alipofukuzwa kutoka mji mkuu wa Almoravid Marrakesh, alikusanya wafuasi na katika Ramadhani ya mwaka 515 (Novemba 1121) alitangaza umahdi wake; harakati ya Almohad ilianza katika milima ya Atlas.", "67c9ea64"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1127-01-01:0":{"b": ["Mfalme wa Aragon aliuzingira Granada lakini alirudi nyuma", "60877b49"], "d": ["Kwa kuhimizwa na Wakristo wa Granada, mfalme wa Aragon aliuzingira mji; kwa ulinzi mkali alilazimika kurudi nyuma mwaka 1127.", "1684bbe7"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1132-01-01:0":{"b": ["Mfalme wa Castile VII. Alfonso aliporo Ishbiliya", "23664808"], "d": ["VII. Alfonso aliporo Ishbiliya katika mwaka 526 (1132); gavana wa mji wa Waalmoravid aliuawa katika mapigano.", "342ff94a"]},
