"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0957-12-01:0":{"b": ["Merzübân afariki Ramazan 346 (Desemba 957); Cüstân achukua nafasi yake.", "90c5eee8"], "d": ["Merzübân afariki Ramazan 346 (Desemba 957); Cüstân achukua nafasi yake.", "90c5eee8"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0962-01-01:0":{"b": ["Wauygur wa Turfan (Kao-ch'ang) watuma ujumbe wa kwanza wa biashara wa watu 42 China.", "f51160fd"], "d": ["Wauygur wa Turfan (Kao-ch'ang) watuma ujumbe wa kwanza wa biashara wa watu 42 China.", "f51160fd"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0966-01-01:0":{"b": ["İbrâhim ashindwa na Vehsûdân na akimbilia Rüknüddevle (355/966).", "e5df11cd"], "d": ["İbrâhim ashindwa na Vehsûdân na akimbilia Rüknüddevle (355/966).", "e5df11cd"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0967-01-01:0":{"b": ["Veşmgîr afariki wakati wa uwindaji (357/967).", "68f9525b"], "d": ["Veşmgîr afariki wakati wa uwindaji (357/967).", "68f9525b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0972-07-01:0":{"b": ["Hasan el-A'sam avamia Remle tena na kushinda jeshi lenye nguvu la Fatimid", "c3b5ad80"], "d": ["Kiongozi wa Kikarmatî Hasan el-A'sam, Ramazan 361 (Julai 972), alivamia Remle tena na kushinda jeshi lenye nguvu la Fatimid; mwaka mmoja baadaye alishambulia Misri kwa nchi kavu na baharini na kuzingira Kairo tena lakini alishindwa na Azîz-Billâh.", "f629e2e1"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:0981-01-01:0":{"b": ["Balozi wa Kichina Wang Yente aanza kuzunguka kati ya Wauygur (981-984); ripoti yake ni chanzo kikuu cha utamaduni wa Uygur wa Turfan.", "478d801b"], "d": ["Balozi wa Kichina Wang Yente aanza kuzunguka kati ya Wauygur (981-984); ripoti yake ni chanzo kikuu cha utamaduni wa Uygur wa Turfan.", "478d801b"]},
