"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1141-01-01:0":{"b": ["Baada ya ushindi wa Katvân, Hârizmşah wakubali kuwa tegemezi wa Karakhitai na kulipa haraj", "5719a5ee"], "d": ["Baada ya Karakhitai kumshinda Sencer huko Katvân na kutawala Mâverâünnehir yote, mwaka huo huo Hârizmşah nao walikubali kuwa tegemezi wa Karakhitai na kulipa haraj (dinari 30,000 kwa mwaka). Utegemezi huu ulidumu hadi 1173, wakati Tekiş alipopanda kiti cha enzi cha Hârizm kwa msaada wa Karakhitai.", "ab6f992b"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1141-01-01:1":{"b": ["Kâkûyî wa mwisho afariki katika vita vya Katvân; Atabeg wa Yezd wachukua nafasi yao Yezd", "272bdc16"], "d": ["Kâkûyî wa mwisho afariki katika vita vya Katvân; Atabeg wa Yezd wachukua nafasi yao Yezd", "272bdc16"]},
"OLAYLAR_ORTACAG_IRAN_HINT_MAGRIB:1142-02-01:0":{"b": ["Gürhan Yeh-lü Ta-şi afariki; mkewe Kuyang (Tu-pu-yen) achukua nafasi yake", "29e8156e"], "d": ["Mtawala wa kwanza wa Karakhitai Gürhan Yeh-lü Ta-şi (1130-1142) alifariki Februari 1142 (au 1143); nafasi yake ilichukuliwa kwa mfuatano na mkewe Tu-pu-yen (Kuyang), mwanawe Yeh-lü Yi-lie, dada yake Yeh-lü-şe au naibu Pu-su-wan. Kwa ushindi wa Katvân (1141) Mâverâünnehir yote na Hârizm zilikuwa zimewekwa chini ya kodi.", "5412642d"]},
